    {
        if (new[] { requireCompleteMaterialization, requireFourCanonicalVariants, requireCanonicalVariantOrdering, requireCanonicalSceneOrdering, requireExactCorrelation, requireDeterministicIdentity, requireNarrativeTraceability, requireSubtitleTraceability, requireVisualTraceability, requireTimingConsistency }.Any(x => !x)) throw new ArgumentException("All projection controls are required.");
