        PolicySchemaVersion = policySchemaVersion == "1.0" ? policySchemaVersion : throw new ArgumentException("Schema must be 1.0.");
        RequireCompleteMaterialization=requireCompleteMaterialization; RequireFourCanonicalVariants=requireFourCanonicalVariants; RequireCanonicalVariantOrdering=requireCanonicalVariantOrdering; RequireCanonicalSceneOrdering=requireCanonicalSceneOrdering; RequireExactCorrelation=requireExactCorrelation; RequireDeterministicIdentity=requireDeterministicIdentity; RequireNarrativeTraceability=requireNarrativeTraceability; RequireSubtitleTraceability=requireSubtitleTraceability; RequireVisualTraceability=requireVisualTraceability; RequireTimingConsistency=requireTimingConsistency;
        RequiredVariantTypes=DocumentaryMediaProjectionInventory.Copy(requiredVariantTypes,nameof(requiredVariantTypes)); SupportedLanguages=DocumentaryMediaProjectionInventory.Copy(supportedLanguages,nameof(supportedLanguages)); SupportedFormats=DocumentaryMediaProjectionInventory.Copy(supportedFormats,nameof(supportedFormats)); SupportedTopicFamilies=DocumentaryMediaProjectionInventory.Copy(supportedTopicFamilies,nameof(supportedTopicFamilies)); LongMinimumSceneCount=longMinimumSceneCount; LongMaximumSceneCount=longMaximumSceneCount; ShortMinimumSceneCount=shortMinimumSceneCount; ShortMaximumSceneCount=shortMaximumSceneCount; LongMinimumDurationSeconds=longMinimumDurationSeconds; LongMaximumDurationSeconds=longMaximumDurationSeconds; ShortMinimumDurationSeconds=shortMinimumDurationSeconds; ShortMaximumDurationSeconds=shortMaximumDurationSeconds; MaximumNarrationCharactersPerScene=maximumNarrationCharactersPerScene; MaximumSubtitleCharactersPerLine=maximumSubtitleCharactersPerLine; MaximumSubtitleLines=maximumSubtitleLines;
